package ru.neverland.townyenvironment.gui;
import java.util.*;
import java.math.BigDecimal;
import java.time.*;
import java.time.format.DateTimeFormatter;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.bukkit.plugin.Plugin;
import ru.neverland.core.*;
import ru.neverland.townyenvironment.service.EnvironmentService;

/** Optional read-only board; refresh waits never replace a player's subsequently opened window. */
final class DistrictEnvironmentMenu {
    private static final int[] SLOTS={10,11,12,13,14,15,16,19,20,21,22,23,24,25,28,29,30,31,32,33,34,37,38,39,40,41,42,43};
    private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm:ss 'МСК'").withZone(ZoneId.of("Europe/Moscow"));
    private final Plugin plugin;private final EnvironmentService service;private final java.util.function.Consumer<Player> back;
    private static final class View implements InventoryHolder{final UUID town;int page;String group;final Map<Integer,String> groups=new HashMap<>();Inventory inventory;View(UUID town,int page){this.town=town;this.page=Math.max(0,page);}@Override public Inventory getInventory(){return inventory;}}
    DistrictEnvironmentMenu(Plugin plugin,EnvironmentService service,java.util.function.Consumer<Player> back){this.plugin=plugin;this.service=service;this.back=back;}
    private boolean allowed(Player player,UUID town){var own=service.town(player);return player.hasPermission("neverlandtownyenvironment.use")&&own!=null&&own.getUUID().equals(town);}
    void open(Player player,int page){try(var guard=SuiteState.guard()){var town=service.requireTown(player);var view=new View(town.getUUID(),page);view.inventory=MenuStyle.inventory(plugin,view,54,"Экология районов");boolean pending=render(view);player.openInventory(view.inventory);if(pending)retry(player,view,6);}}
    private void detail(Player player,View previous,String group,int page){var view=new View(previous.town,page);view.group=group;view.inventory=MenuStyle.inventory(plugin,view,54,"Источники района");boolean pending=render(view);player.openInventory(view.inventory);if(pending)retry(player,view,6);}
    private boolean render(View view){view.groups.clear();service.refreshDistricts(view.town);var report=service.districts(view.town);view.inventory.clear();view.inventory.setItem(48,item(Material.BELL,"К экологии города","Общие показатели и действующие штрафы."));view.inventory.setItem(49,item(Material.SUNFLOWER,"Обновить","Проверить источники по районам."));
        if(!Boolean.TRUE.equals(report.get("available"))){boolean pending=Boolean.TRUE.equals(report.get("pending"));view.inventory.setItem(22,item(pending?Material.CLOCK:Material.BARRIER,pending?"Сведения готовятся":"Сведения недоступны",String.valueOf(report.getOrDefault("issue","Попробуйте позже")),"Загрязнение города и настройки сохранены."));return pending;}
        if(view.group!=null)return renderSources(view,report);
        var totals=map(report.get("totals"));view.inventory.setItem(4,item(Material.GRASS_BLOCK,"Источники и зелёные здания","Выбросы за цикл: +"+decimal(totals.get("emissions")),"Очистка за цикл: −"+decimal(totals.get("cleaning")),"Общее изменение: "+decimal(totals.get("change")),"Это вклад районов в единый показатель города.","Отдельных штрафов для районов нет.","Источники: "+date(report.get("sourceAt")),"Расчёт: "+date(report.get("checkedAt"))));
        var rows=new TreeMap<>(map(report.get("rows")));var entries=new ArrayList<>(rows.entrySet());int pages=Math.max(1,(entries.size()+SLOTS.length-1)/SLOTS.length);view.page=Math.min(view.page,pages-1);
        for(int i=view.page*SLOTS.length;i<Math.min(entries.size(),(view.page+1)*SLOTS.length);i++){var row=map(entries.get(i).getValue());var lore=new ArrayList<String>();lore.add("Выбросы: +"+decimal(row.get("emissions"))+" за цикл");lore.add("Очистка: −"+decimal(row.get("cleaning"))+" за цикл");lore.add("Вклад в изменение: "+decimal(row.get("change")));lore.add("Работающих зелёных зданий: "+row.get("greenBuildings"));var sources=new TreeMap<>(map(row.get("sources")));int shown=0;for(var entry:sources.entrySet()){if(shown++>=10)break;var source=map(entry.getValue());lore.add(source.get("name")+(Boolean.TRUE.equals(source.get("natural"))?"":" · уровень "+source.get("level")));lore.add("  +"+decimal(source.get("emissions"))+" выбросов; −"+decimal(source.get("cleaning"))+" очистки");}if(sources.size()>10)lore.add("Ещё источников: "+(sources.size()-10));lore.add("Нажмите, чтобы посмотреть все источники.");view.groups.put(SLOTS[i%SLOTS.length],entries.get(i).getKey());if(!Boolean.TRUE.equals(row.get("district")))lore.add("Природа и постройки вне назначенных районов.");view.inventory.setItem(SLOTS[i%SLOTS.length],item(((Number)row.get("greenBuildings")).intValue()>0?Material.OAK_SAPLING:Material.FILLED_MAP,String.valueOf(row.get("name")),lore.toArray(String[]::new)));}
        if(view.page>0)view.inventory.setItem(45,item(Material.ARROW,"Предыдущая страница"));if(view.page+1<pages)view.inventory.setItem(53,item(Material.ARROW,"Следующая страница"));view.inventory.setItem(50,item(Material.PAPER,"Страница "+(view.page+1)+" / "+pages));return false;
    }
    private boolean renderSources(View view,Map<String,Object> report){var row=map(map(report.get("rows")).get(view.group));if(row.isEmpty()){view.inventory.setItem(22,item(Material.BARRIER,"Район больше не найден","Вернитесь к списку районов."));return false;}view.inventory.setItem(4,item(Material.GRASS_BLOCK,String.valueOf(row.get("name")),"Все работающие источники этого района.","Выбросы +"+decimal(row.get("emissions"))+"; очистка −"+decimal(row.get("cleaning"))));view.inventory.setItem(48,item(Material.BELL,"К списку районов"));var entries=new ArrayList<>(new TreeMap<>(map(row.get("sources"))).entrySet());int pages=Math.max(1,(entries.size()+SLOTS.length-1)/SLOTS.length);view.page=Math.min(view.page,pages-1);for(int i=view.page*SLOTS.length;i<Math.min(entries.size(),(view.page+1)*SLOTS.length);i++){var source=map(entries.get(i).getValue());boolean nature=Boolean.TRUE.equals(source.get("natural"));view.inventory.setItem(SLOTS[i%SLOTS.length],item(new BigDecimal((String)source.get("cleaning")).signum()>0?Material.OAK_SAPLING:Material.BLAST_FURNACE,String.valueOf(source.get("name")),nature?"Природное восстановление всего города":"Действующий уровень: "+source.get("level"),"Выбросы: +"+decimal(source.get("emissions"))+" за цикл","Очистка: −"+decimal(source.get("cleaning"))+" за цикл"));}if(view.page>0)view.inventory.setItem(45,item(Material.ARROW,"Предыдущая страница"));if(view.page+1<pages)view.inventory.setItem(53,item(Material.ARROW,"Следующая страница"));view.inventory.setItem(50,item(Material.PAPER,"Страница "+(view.page+1)+" / "+pages));return false;}
    private void retry(Player player,View view,int attempts){if(attempts<=0)return;SuiteScheduler.entityLater(plugin,player,()->{if(!player.isOnline()||player.getOpenInventory().getTopInventory()!=view.inventory)return;if(!allowed(player,view.town)){player.closeInventory();return;}if(render(view))retry(player,view,attempts-1);},null,10);}
    boolean click(InventoryClickEvent event){if(!(event.getView().getTopInventory().getHolder()instanceof View view))return false;event.setCancelled(true);if(!(event.getWhoClicked()instanceof Player player))return true;if(!allowed(player,view.town)){player.closeInventory();return true;}int slot=event.getRawSlot();if(!view.groups.containsKey(slot)&&!Set.of(45,48,49,53).contains(slot)||slot<0||slot>=54||view.inventory.getItem(slot)==null)return true;SuiteScheduler.entity(plugin,player,()->{if(!player.isOnline()||player.getOpenInventory().getTopInventory()!=view.inventory)return;if(!allowed(player,view.town)){player.closeInventory();return;}if(view.groups.containsKey(slot))detail(player,view,view.groups.get(slot),0);else if(slot==48){if(view.group!=null)open(player,0);else back.accept(player);}else{int page=slot==45?view.page-1:slot==53?view.page+1:view.page;if(view.group==null)open(player,page);else detail(player,view,view.group,page);}});return true;}
    boolean drag(InventoryDragEvent event){if(!(event.getView().getTopInventory().getHolder()instanceof View))return false;event.setCancelled(true);return true;}
    void close(){SuiteScheduler.cleanupPlayers(plugin,player->{if(player.getOpenInventory().getTopInventory().getHolder()instanceof View)player.closeInventory();});}
    @SuppressWarnings("unchecked")private static Map<String,Object> map(Object value){return value instanceof Map<?,?>m?(Map<String,Object>)m:Map.of();}private static String decimal(Object value){try{return new BigDecimal(String.valueOf(value)).stripTrailingZeros().toPlainString();}catch(NumberFormatException error){return "нет данных";}}private static String date(Object value){return value instanceof Number n&&n.longValue()>0?DATE.format(Instant.ofEpochMilli(n.longValue())):"ожидаем сведения";}
    private static ItemStack item(Material material,String name,String... lore){var item=new ItemStack(material);var meta=item.getItemMeta();meta.setDisplayName(MenuStyle.nameLegacy("§b"+name));meta.setLore(MenuStyle.loreStrings(Arrays.stream(lore).map(s->"§7"+s).toList()));meta.addItemFlags(ItemFlag.HIDE_ATTRIBUTES);item.setItemMeta(meta);return item;}
}
